export const pm11Choices=[['abstract','final','private','protected','public','static'],['i','i - 1','i * 2','i / 2','i / 2 + 1','i + 1'],['[i + 1][0]','[i + 1][1]','[i + 1][i]','[i][0]','[i][1]','[i][i + 1]'],['extends','implements','imports','public','throws'],['((RatePlan) this)','RatePlan','super','this','TieredRateTable','TierTable'],['(1.0 - discountTiers.map(amount))','(1.0 - discountTiers.map(basicCharge))','(1.0 - discountTiers.map(price))','discountTiers.map(amount)','discountTiers.map(basicCharge)','discountTiers.map(price)']];
