/** Length-intersection integration in exact milli-yen, independent of source's loops. */
export function pm11Price(v:number,plan:number,amount10:number){const c=pm11Review[v],edges=[0,...c.bounds.map(n=>n*10),amount10],widths=[0,1,2].map(i=>Math.max(0,Math.min(amount10,edges[i+1])-edges[i]));const milli=BigInt(c.basic[plan])*10n+widths.reduce((sum,n,i)=>sum+BigInt(n)*BigInt(c.rates[plan][i]),0n);return Number(milli/1000n);}
export function pm11Discount(price:number){const percent=price<5000?1:price<8000?3:5;return Math.trunc(price*(100-percent)/100);}
export function pm11ProbeAmounts(v:number){const [a,b]=pm11Review[v].bounds;return[0,1,a*10-1,a*10,a*10+1,b*10-1,b*10,b*10+1,pm11Review[v].amount10,12005];}
export function pm11Output(v:number){const c=pm11Review[v],a=pm11Price(v,0,c.amount10),b=pm11Price(v,1,c.amount10),d=a-b;return d===0?'両プランで同額':`プラン${d<0?'A':'B'}が${Math.abs(d)}円安い`;}
